-- Posts de exemplo (56) para ver o feed com conteúdo de verdade. Ids fixos: posts em
-- 00000000-0000-4000-b000-* (reações e comentários vão junto ao apagar). Para remover tudo:
--   delete from public.posts where id::text like '00000000-0000-4000-b000-%';
-- Helena Souza (003) está suspensa: os posts dela vão para Maria Lorena e Pedro Costa.
-- Só entram se os perfis de exemplo (00000000-0000-4000-a000-*) existirem; seguro rodar de novo.
insert into public.posts (id, author_id, type, title, body, image_url, recipe, publish_at, created_at, updated_at)
select v.id::uuid,
  (case when v.author = '00000000-0000-4000-a000-000000000003' then (case when right(v.id, 2)::int % 2 = 0 then '00000000-0000-4000-a000-000000000001' else '00000000-0000-4000-a000-000000000002' end) else v.author end)::uuid,
  v.type::post_type, v.title, v.body, v.img, v.recipe::jsonb, now() - (v.mins || ' minutes')::interval, now() - (v.mins || ' minutes')::interval, now() - (v.mins || ' minutes')::interval
from (values
('00000000-0000-4000-b000-000000000001','00000000-0000-4000-a000-000000000002','receita','Mingau de aveia com maçã e canela','Aveia cozida no leite com pedaços de maçã e uma pitada de canela. Fica pronta em dez minutos e segura a fome até o almoço. Eu faço na véspera e esquento de manhã, com um fio de mel por cima. Para quem tem pressa, vale preparar uma porção dupla e guardar na geladeira por até dois dias.','/images/social/mesa-cafe-da-manha.jpg','{"category":"Receitas","prepTime":"10 min","servings":"2 porções","difficulty":"Fácil","ingredients":["1 xícara de aveia em flocos","2 xícaras de leite","1 maçã picada","Canela a gosto","Mel (opcional)"],"steps":["Leve a aveia e o leite ao fogo baixo, mexendo.","Junte a maçã e a canela e cozinhe até engrossar.","Sirva morno com mel."]}',120),
('00000000-0000-4000-b000-000000000002','00000000-0000-4000-a000-000000000001','experiencia','Três semanas sem pular o café da manhã','Sempre saí de casa correndo e só comia algo às onze. Combinei comigo mesma de tomar um café da manhã simples, mesmo que fosse só uma fruta com iogurte. Na segunda semana já percebi menos beliscos à tarde. Não é milagre, é rotina. Quem mais está tentando criar esse hábito?','/images/social/iogurte-morango.jpg',null,378),
('00000000-0000-4000-b000-000000000003','00000000-0000-4000-a000-000000000101','pergunta','Como aumentar as fibras sem passar mal?','Quero comer mais fibras, mas sempre que aumento de uma vez fico com a barriga estufada. Existe um jeito de ir devagar? Quais alimentos vocês incluíram primeiro?',null,null,636),
('00000000-0000-4000-b000-000000000004','00000000-0000-4000-a000-000000000102','geral','Feira de sábado: o que está na estação','Fui à feira cedo e voltei com a sacola cheia de couve, rabanete, laranja-lima e abobrinha. Quando a gente compra o que está na época, paga menos e o sabor é outro. Escrevam o que vocês acharam de bom por aí.','/images/social/feira-legumes.jpg',null,894),
('00000000-0000-4000-b000-000000000005','00000000-0000-4000-a000-000000000103','receita','Salada de macarrão integral com legumes','Uma salada fria para levar na marmita: macarrão integral al dente, tomate-cereja, pepino, cenoura ralada e folhas verdes. O molho é azeite, limão, uma colher de mostarda e sal. Rende bem e não murcha até a hora do almoço.','/images/social/salada-macarrao.jpg','{"category":"Receitas","prepTime":"25 min","servings":"4 porções","difficulty":"Fácil","ingredients":["250 g de macarrão integral","1 xícara de tomate-cereja","1 pepino","1 cenoura ralada","Azeite, limão e mostarda"],"steps":["Cozinhe o macarrão e esfrie em água corrente.","Misture os legumes picados.","Tempere e leve à geladeira por 20 minutos."]}',1152),
('00000000-0000-4000-b000-000000000006','00000000-0000-4000-a000-000000000101','experiencia','O que mudou quando comecei a planejar o cardápio','Eu jogava comida fora toda semana. Passei a sentar domingo à noite, ver o que tinha em casa e montar cinco jantares simples. A lista de compras ficou menor, o lixo também. No começo parecia trabalho demais; hoje leva quinze minutos.',null,null,1410),
('00000000-0000-4000-b000-000000000007','00000000-0000-4000-a000-000000000102','pergunta','Vale a pena trocar o açúcar por adoçante?','Tomo café com duas colheres de açúcar e queria reduzir. Adoçante resolve ou só troco um problema por outro? Prefiro ouvir de quem já passou por isso e, se algum profissional puder comentar, melhor ainda.',null,null,1668),
('00000000-0000-4000-b000-000000000008','00000000-0000-4000-a000-000000000103','receita','Panqueca de banana com aveia, sem farinha','Duas bananas maduras, dois ovos e meia xícara de aveia no liquidificador. Frigideira antiaderente, fogo baixo e paciência para virar. Fica macia e levemente doce, dispensa açúcar. Aqui em casa vai com frutas vermelhas.','/images/social/panquecas.jpg','{"category":"Receitas","prepTime":"15 min","servings":"3 porções","difficulty":"Fácil","ingredients":["2 bananas maduras","2 ovos","1/2 xícara de aveia","Canela (opcional)"],"steps":["Bata tudo no liquidificador.","Doure pequenas porções em fogo baixo.","Sirva com frutas."]}',1926),
('00000000-0000-4000-b000-000000000009','00000000-0000-4000-a000-000000000101','geral','Água: como eu criei o hábito de beber mais','Deixei uma garrafa de um litro na mesa de trabalho e coloquei duas metas: terminá-la até o almoço e de novo até o fim do dia. Funcionou melhor do que qualquer lembrete no celular. Fatias de pepino e limão ajudam a variar.','/images/social/pepino-limao.jpg',null,2184),
('00000000-0000-4000-b000-000000000010','00000000-0000-4000-a000-000000000002','experiencia','Cozinhar com as crianças mudou a hora do jantar','Meus filhos recusavam legumes. Chamei os dois para lavar, picar o que é seguro e montar o próprio prato. Eles ainda reclamam de uma coisa ou outra, mas provam tudo. O segredo foi tirar a pressão e transformar em brincadeira.','/images/social/cozinhando-juntos.jpg',null,2442),
('00000000-0000-4000-b000-000000000011','00000000-0000-4000-a000-000000000002','pergunta','Preciso de proteína extra se treino três vezes por semana?','Faço musculação três vezes por semana e ouço de tudo: que preciso de suplemento, que não preciso de nada. Como saber o quanto de proteína faz sentido para mim? Quero entender antes de gastar dinheiro.',null,null,2700),
('00000000-0000-4000-b000-000000000012','00000000-0000-4000-a000-000000000001','receita','Bowl de grãos com legumes assados','Quinoa ou arroz integral, abóbora e brócolis assados com azeite e alho, grão-de-bico e um molho de iogurte com limão. Monto o bowl de manhã e levo na marmita. A combinação de grãos, legumes e leguminosas deixa o prato completo.','/images/social/bowl-graos.jpg','{"category":"Receitas","prepTime":"40 min","servings":"2 porções","difficulty":"Médio","ingredients":["1 xícara de quinoa cozida","2 xícaras de abóbora e brócolis","1 xícara de grão-de-bico","Iogurte natural e limão"],"steps":["Asse os legumes a 200 °C por 25 minutos.","Misture o iogurte com limão e sal.","Monte o bowl e finalize com o molho."]}',2958),
('00000000-0000-4000-b000-000000000013','00000000-0000-4000-a000-000000000002','geral','Guia Alimentar: prefira alimentos in natura','O Guia Alimentar para a População Brasileira recomenda que a base da alimentação sejam alimentos in natura ou minimamente processados, como feijão, arroz, frutas, legumes e ovos. Fica a dica para quem está começando: olhe a lista de ingredientes e prefira rótulos curtos.','/images/social/ingredientes-mesa.jpg',null,3216),
('00000000-0000-4000-b000-000000000014','00000000-0000-4000-a000-000000000001','experiencia','Meu primeiro mês de marmitas','Comecei por vontade de economizar e acabei ganhando tempo e disposição. Cozinho domingo e quarta. Congelo o feijão em porções, deixo legumes lavados e a proteína pronta. Na primeira semana errei o sal; na quarta já estava no ritmo.',null,null,3474),
('00000000-0000-4000-b000-000000000015','00000000-0000-4000-a000-000000000101','pergunta','Alguém tem receita de lanche escolar que não esquenta?','Minha filha leva o lanche e só come na hora do recreio, quase duas horas depois. Procuro ideias que aguentem fora da geladeira sem estragar nem ficar murcha. Aceito tudo!',null,null,3732),
('00000000-0000-4000-b000-000000000016','00000000-0000-4000-a000-000000000102','receita','Salada colorida com molho de iogurte','Folhas, tomate, milho, cenoura e grão-de-bico. O molho leva iogurte natural, limão, sal e ervas. Fica cremoso sem maionese. Serve de acompanhamento ou refeição leve.','/images/social/salada-colorida.jpg','{"category":"Receitas","prepTime":"15 min","servings":"3 porções","difficulty":"Fácil","ingredients":["Folhas variadas","1 tomate","1/2 xícara de milho","1 cenoura","Iogurte natural e limão"],"steps":["Lave e corte tudo.","Misture o molho.","Tempere na hora de servir."]}',3990),
('00000000-0000-4000-b000-000000000017','00000000-0000-4000-a000-000000000103','geral','Respire antes de comer','Um exercício simples: antes da primeira garfada, três respirações lentas. Parece pouco, mas ajuda a notar a fome de verdade e a comer com mais calma. Experimente por uma semana e conte aqui como foi.',null,null,4248),
('00000000-0000-4000-b000-000000000018','00000000-0000-4000-a000-000000000101','experiencia','Parei de me pesar todo dia','Me pesava todas as manhãs e o número decidia o meu humor. Conversei com minha nutricionista e combinamos olhar outras coisas: disposição, sono, como a roupa veste. Foi libertador. Cada pessoa tem o seu ritmo.',null,null,4506),
('00000000-0000-4000-b000-000000000019','00000000-0000-4000-a000-000000000102','pergunta','Como incluir peixe na rotina gastando pouco?','Quero comer peixe uma ou duas vezes por semana, mas o preço assusta. Sardinha, tilápia congelada, atum de lata? O que vocês compram e como preparam?',null,null,4764),
('00000000-0000-4000-b000-000000000020','00000000-0000-4000-a000-000000000103','receita','Salmão assado com limão e ervas','Filé de salmão temperado com limão, alho, azeite e ervas frescas. Vai ao forno por quinze minutos e acompanha bem arroz integral e legumes no vapor. Uma refeição elegante e sem complicação.','/images/social/bowl-salmao.jpg','{"category":"Receitas","prepTime":"25 min","servings":"2 porções","difficulty":"Fácil","ingredients":["2 filés de salmão","1 limão","2 dentes de alho","Azeite e ervas"],"steps":["Tempere o peixe e deixe 10 minutos.","Asse a 200 °C por 15 minutos.","Sirva com legumes."]}',5022),
('00000000-0000-4000-b000-000000000021','00000000-0000-4000-a000-000000000101','geral','Sono e fome andam juntos','Dormi mal por três noites e percebi que comi mais doce e mais tarde. Não é coincidência: o descanso influencia o apetite. Cuidar do sono também é cuidar da alimentação.',null,null,5280),
('00000000-0000-4000-b000-000000000022','00000000-0000-4000-a000-000000000002','experiencia','Jardim de temperos na janela','Plantei manjericão, cebolinha e hortelã em vasos pequenos. Em um mês já estava colhendo. Tempero fresco muda qualquer prato e ainda reduz o sal. Quem tem pouco espaço consegue.','/images/social/couve.jpg',null,5538),
('00000000-0000-4000-b000-000000000023','00000000-0000-4000-a000-000000000002','pergunta','Frutas congeladas valem como as frescas?','Moro longe do mercado e compro frutas congeladas para as vitaminas. Perdem muito valor nutritivo? Alguém sabe dizer?',null,null,5796),
('00000000-0000-4000-b000-000000000024','00000000-0000-4000-a000-000000000001','receita','Vitamina de morango com iogurte e aveia','Morangos, iogurte natural, um punhado de aveia e gelo. Bata e sirva na hora. Dá para trocar por qualquer fruta da estação. Ótima para o lanche da tarde.','/images/social/morango.jpg','{"category":"Receitas","prepTime":"5 min","servings":"1 porção","difficulty":"Fácil","ingredients":["1 xícara de morangos","1 pote de iogurte natural","1 colher de aveia","Gelo"],"steps":["Bata tudo no liquidificador.","Sirva imediatamente."]}',6054),
('00000000-0000-4000-b000-000000000025','00000000-0000-4000-a000-000000000002','geral','Como ler um rótulo em dez segundos','Olhe a lista de ingredientes: quanto menor, melhor. Se o primeiro item for açúcar, é sinal para repensar. Procure a lupa de alto teor de açúcar, gordura saturada e sódio nas embalagens. Na dúvida, escaneie o código de barras no app.',null,null,6312),
('00000000-0000-4000-b000-000000000026','00000000-0000-4000-a000-000000000001','experiencia','Voltei a correr sem pressa','Comecei andando e correndo em intervalos de um minuto. Hoje faço trinta minutos contínuos, três vezes por semana. O combinado comigo é nunca ir além do que o corpo aceita. A alimentação acompanhou: mais água e um lanche leve antes de sair.','/images/social/exercicio.jpg',null,6570),
('00000000-0000-4000-b000-000000000027','00000000-0000-4000-a000-000000000101','pergunta','Dicas de lanche para a tarde que não seja doce?','Bate quatro da tarde e eu corro para o chocolate. Quero alternativas salgadas e saudáveis que sejam fáceis de levar para o escritório.',null,null,6828),
('00000000-0000-4000-b000-000000000028','00000000-0000-4000-a000-000000000102','receita','Espetinhos de frango com legumes','Cubos de frango marinados em limão e ervas intercalados com pimentão, cebola e abobrinha. Vão à grelha ou à frigideira. Servem bem com arroz integral e salada.','/images/social/espetinhos.jpg','{"category":"Receitas","prepTime":"35 min","servings":"4 porções","difficulty":"Médio","ingredients":["500 g de peito de frango","Pimentão, cebola e abobrinha","Limão, alho e ervas"],"steps":["Marine o frango por 20 minutos.","Monte os espetos.","Grelhe até dourar."]}',7086),
('00000000-0000-4000-b000-000000000029','00000000-0000-4000-a000-000000000103','geral','Comer em família faz bem','Sentar à mesa sem telas, conversar e servir-se com calma. A refeição em companhia melhora a relação com a comida e fortalece os vínculos. Tente fazer ao menos uma refeição por dia assim.','/images/social/pratos-mesa.jpg',null,7344),
('00000000-0000-4000-b000-000000000030','00000000-0000-4000-a000-000000000101','experiencia','Aprendi a gostar de feijão com couve','Cresci detestando couve. Aprendi a refogá-la bem fininha com alho e agora peço repeteco. Às vezes é questão de preparo, não de gosto.',null,null,7602),
('00000000-0000-4000-b000-000000000031','00000000-0000-4000-a000-000000000102','pergunta','Ovo todo dia faz mal?','Tomo café com dois ovos mexidos todo dia e ouvi opiniões contrárias. Existe um limite? Gostaria de ouvir uma orientação profissional.',null,null,7860),
('00000000-0000-4000-b000-000000000032','00000000-0000-4000-a000-000000000103','receita','Rabanada assada com frutas','Pão amanhecido embebido em leite e ovo, assado em vez de frito e coberto com frutas fatiadas. Fica macia por dentro e douradinha por fora. Excelente para aproveitar sobras.','/images/social/rabanada-frutas.jpg','{"category":"Receitas","prepTime":"30 min","servings":"4 porções","difficulty":"Fácil","ingredients":["6 fatias de pão","1 xícara de leite","2 ovos","Canela e frutas"],"steps":["Misture leite e ovos.","Embeba o pão e disponha em assadeira.","Asse a 200 °C até dourar."]}',8118),
('00000000-0000-4000-b000-000000000033','00000000-0000-4000-a000-000000000101','geral','Reaproveitar é cuidar','Talos de couve viram refogado, casca de banana vira bolo, sobras de arroz viram bolinho. Aproveitar o alimento por inteiro reduz o desperdício e o gasto no mercado.','/images/social/hortifruti.jpg',null,8376),
('00000000-0000-4000-b000-000000000034','00000000-0000-4000-a000-000000000002','experiencia','Meu relato sobre comer sem culpa','Durante anos classifiquei comida em boa e ruim. Em acompanhamento, aprendi a olhar o padrão da semana e não o prato isolado. Se um dia sai do planejado, o seguinte recomeça. A culpa nunca ajudou ninguém.',null,null,8634),
('00000000-0000-4000-b000-000000000035','00000000-0000-4000-a000-000000000002','pergunta','Qual a melhor hora para treinar em jejum ou alimentado?','Treino às seis da manhã e fico em dúvida se devo comer antes. Alguém passou por isso? Gostaria também de ouvir um profissional de educação física.',null,null,8892),
('00000000-0000-4000-b000-000000000036','00000000-0000-4000-a000-000000000001','receita','Sopa de legumes cremosa sem creme','Abóbora, cenoura, batata e cebola cozidas e batidas com um pouco do caldo. A cremosidade vem dos próprios legumes. Finalizo com salsinha e um fio de azeite.','/images/social/legumes-tabua.jpg','{"category":"Receitas","prepTime":"35 min","servings":"4 porções","difficulty":"Fácil","ingredients":["300 g de abóbora","2 cenouras","1 batata","1 cebola","Salsinha"],"steps":["Cozinhe os legumes em água com sal.","Bata com parte do caldo.","Ajuste o tempero e sirva."]}',9150),
('00000000-0000-4000-b000-000000000037','00000000-0000-4000-a000-000000000002','geral','Prato equilibrado, sem contar nada','Metade do prato com legumes e verduras, um quarto com grãos e um quarto com proteína. Não precisa de balança, só de olhar para o prato. É um bom ponto de partida para o dia a dia.','/images/social/prato-minimalista.jpg',null,9408),
('00000000-0000-4000-b000-000000000038','00000000-0000-4000-a000-000000000001','experiencia','Quando a dieta virou rotina','Parei de chamar de dieta. Hoje é só a forma como eu como. Cozinho mais, peço menos delivery e saio para almoçar com amigos sem estresse. Consistência vale mais que perfeição.',null,null,9666),
('00000000-0000-4000-b000-000000000039','00000000-0000-4000-a000-000000000101','pergunta','Como lidar com a vontade de doce à noite?','Depois do jantar a vontade de doce aparece com força. Já tentei fruta, mas nem sempre resolve. Que estratégias funcionam para vocês?',null,null,9924),
('00000000-0000-4000-b000-000000000040','00000000-0000-4000-a000-000000000102','receita','Bowl de frutas com granola caseira','Frutas picadas, iogurte natural e uma granola de aveia, castanhas e mel assada no forno. Um café da manhã bonito e saciante.','/images/social/bowl-frutas.jpg','{"category":"Receitas","prepTime":"30 min","servings":"4 porções","difficulty":"Médio","ingredients":["2 xícaras de aveia","1/2 xícara de castanhas","3 colheres de mel","Frutas variadas","Iogurte natural"],"steps":["Misture aveia, castanhas e mel.","Asse a 160 °C por 20 minutos, mexendo.","Monte com frutas e iogurte."]}',10182),
('00000000-0000-4000-b000-000000000041','00000000-0000-4000-a000-000000000103','geral','Comida de verdade em bairro sem feira?','Mesmo sem feira por perto, dá para comprar bem: procure mercadinhos com hortifruti, grupos de compra coletiva e cestas de produtores. Alguém conhece uma solução na sua região?','/images/social/frutas-variadas.jpg',null,10440),
('00000000-0000-4000-b000-000000000042','00000000-0000-4000-a000-000000000101','experiencia','Minha primeira consulta online','Tinha receio, mas a consulta por vídeo foi tranquila. Mostrei minha rotina, falamos das dificuldades e saí com metas pequenas. Receber o plano pelo app facilitou muito.',null,null,10698),
('00000000-0000-4000-b000-000000000043','00000000-0000-4000-a000-000000000102','pergunta','O que levar para um piquenique saudável?','Vamos fazer um piquenique com amigos e queria opções práticas, que não estraguem no calor e agradem a todos. Sugestões?',null,null,10956),
('00000000-0000-4000-b000-000000000044','00000000-0000-4000-a000-000000000103','receita','Pasta de grão-de-bico caseira','Grão-de-bico cozido, limão, alho, azeite e um pouco de água. Bata até ficar cremoso. Combina com palitos de cenoura e pepino ou torradas integrais.','/images/social/bowl-legumes.jpg','{"category":"Receitas","prepTime":"10 min","servings":"6 porções","difficulty":"Fácil","ingredients":["2 xícaras de grão-de-bico cozido","1 limão","1 dente de alho","3 colheres de azeite"],"steps":["Bata tudo no processador.","Ajuste sal e consistência com água."]}',11214),
('00000000-0000-4000-b000-000000000045','00000000-0000-4000-a000-000000000101','geral','Pequenas metas, grandes resultados','Em vez de mudar tudo de uma vez, escolha uma meta por semana: mais água, uma fruta por dia, caminhar quinze minutos. Pequenas conquistas sustentam a motivação.',null,null,11472),
('00000000-0000-4000-b000-000000000046','00000000-0000-4000-a000-000000000002','experiencia','Descobrindo novas frutas','Peguei o hábito de provar uma fruta nova por semana. Já tive pitaya, carambola e caju fresco. Além do sabor, descobri combinações que nunca tinha pensado.','/images/social/frutas-tropicais.jpg',null,11730),
('00000000-0000-4000-b000-000000000047','00000000-0000-4000-a000-000000000002','pergunta','Leite vegetal substitui o de vaca?','Quero reduzir laticínios. Leites vegetais têm os mesmos nutrientes? Preciso me preocupar com cálcio?','/images/social/leite.jpg',null,11988),
('00000000-0000-4000-b000-000000000048','00000000-0000-4000-a000-000000000001','receita','Peixe ao molho de tomate fresco','Filés de peixe branco cozidos em molho de tomate com cebola, alho e manjericão. Rápido, leve e muito saboroso. Acompanha bem arroz e salada verde.','/images/social/peixe-molho.jpg','{"category":"Receitas","prepTime":"30 min","servings":"3 porções","difficulty":"Fácil","ingredients":["3 filés de peixe branco","4 tomates","1 cebola","Alho e manjericão"],"steps":["Refogue a cebola e o alho.","Junte o tomate e cozinhe 10 minutos.","Coloque o peixe e cozinhe tampado por 8 minutos."]}',12246),
('00000000-0000-4000-b000-000000000049','00000000-0000-4000-a000-000000000002','geral','Hidratação no calor','Nos dias quentes, além de água, frutas como melancia e melão ajudam a hidratar. Evite esperar a sede aparecer e mantenha sempre uma garrafa por perto.','/images/social/agua-copo.jpg',null,12504),
('00000000-0000-4000-b000-000000000050','00000000-0000-4000-a000-000000000001','experiencia','Um ano de grupo de caminhada','Começamos em quatro vizinhas e hoje somos vinte. Caminhamos de manhã, trocamos receitas e nos apoiamos. O melhor remédio foi a companhia.',null,null,12762),
('00000000-0000-4000-b000-000000000051','00000000-0000-4000-a000-000000000101','receita','Salada de rabanete com laranja','Rabanete fatiado fino, gomos de laranja, folhas e um pouco de hortelã. Tempere com azeite e sal. Refrescante e crocante.','/images/social/salada-rabanete.jpg','{"category":"Receitas","prepTime":"10 min","servings":"2 porções","difficulty":"Fácil","ingredients":["6 rabanetes","1 laranja","Folhas verdes","Hortelã","Azeite e sal"],"steps":["Fatie os rabanetes.","Junte a laranja e as folhas.","Tempere e sirva."]}',13020),
('00000000-0000-4000-b000-000000000052','00000000-0000-4000-a000-000000000102','pergunta','Qual a melhor forma de começar a cozinhar?','Sempre dependi de comida pronta. Quero aprender a cozinhar do zero. Por onde começo? Recomendações de receitas básicas e utensílios essenciais são bem-vindas.',null,null,13278),
('00000000-0000-4000-b000-000000000053','00000000-0000-4000-a000-000000000103','geral','Dia Mundial da Alimentação: 16 de outubro','No dia 16 de outubro, a data lembra a importância de garantir comida de qualidade para todos. Que tal compartilhar um prato de casa e conversar com a família sobre de onde vem o que comemos?','/images/social/espinafre.jpg',null,13536),
('00000000-0000-4000-b000-000000000054','00000000-0000-4000-a000-000000000101','experiencia','Reduzi o sal sem perder o sabor','Troquei o sal por ervas, limão e especiarias. Em duas semanas o paladar se acostumou, e agora percebo como alimentos industrializados são salgados. Valeu cada tentativa.',null,null,13794),
('00000000-0000-4000-b000-000000000055','00000000-0000-4000-a000-000000000102','receita','Frango grelhado com abacaxi','Peito de frango temperado com alho e limão, grelhado com fatias de abacaxi. O açúcar natural da fruta caramelizou e deu um contraste perfeito.','/images/social/frango-grelhado.jpg','{"category":"Receitas","prepTime":"25 min","servings":"2 porções","difficulty":"Fácil","ingredients":["2 filés de frango","4 fatias de abacaxi","Alho, limão e sal"],"steps":["Tempere o frango.","Grelhe os dois lados.","Grelhe o abacaxi e sirva junto."]}',14052),
('00000000-0000-4000-b000-000000000056','00000000-0000-4000-a000-000000000103','pergunta','Como organizar a geladeira para durar mais?','Sempre estrago folhas e frutas. Existe uma ordem ideal? O que fica em cada prateleira? Queria dicas práticas.','/images/social/hortifruti.jpg',null,14310)
) as v(id, author, type, title, body, img, recipe, mins)
